ParameterValue = StrictBool | StrictInt | StrictFloat | StrictStr | ExactReference
ParameterName = Identifier


class ParameterSlot(Contract):
    name: ParameterName
    kind: Literal["integer", "number", "boolean", "choice", "reference"]
    required: bool = True
    default: ParameterValue | None = None
    minimum: float | None = Field(default=None, allow_inf_nan=False)
    maximum: float | None = Field(default=None, allow_inf_nan=False)
    choices: Annotated[tuple[Identifier, ...], Field(max_length=128)] = ()

    def resolve(self, value: ParameterValue) -> ParameterValue:
        if self.kind == "integer":
            valid = type(value) is int
        elif self.kind == "number":
            valid = type(value) in {int, float}
        elif self.kind == "boolean":
            valid = type(value) is bool
        elif self.kind == "choice":
            valid = type(value) is str and value in self.choices
        else:
            valid = isinstance(value, ExactReference)
        if not valid:
            raise ForgeError(
                "research_parameter_invalid", "parameter type or choice differs"
            )
        if self.kind in {"integer", "number"}:
            import math

            if not isinstance(value, (int, float)):
                raise ForgeError("research_parameter_invalid", "numeric value required")
            if (isinstance(value, float) and not math.isfinite(value)) or (
                self.minimum is not None
                and value < self.minimum
                or self.maximum is not None
                and value > self.maximum
            ):
                raise ForgeError(
                    "research_parameter_invalid", "parameter exceeds declared bounds"
                )
        return value

    @model_validator(mode="after")
    def declaration(self):
        if (self.kind == "choice") != bool(self.choices):
            raise ValueError("choice slots declare their allowed values")
        if len(set(self.choices)) != len(self.choices):
            raise ValueError("duplicate parameter choice")
        if self.kind not in {"integer", "number"} and (
            self.minimum is not None or self.maximum is not None
        ):
            raise ValueError("only numeric parameters have numeric bounds")
        if self.kind in {"integer", "number"} and (
            self.minimum is None or self.maximum is None
        ):
            raise ValueError("numeric parameters require explicit bounds")
        if (
            self.minimum is not None
            and self.maximum is not None
            and self.minimum > self.maximum
        ):
            raise ValueError("parameter bounds are reversed")
        if self.default is not None:
            self.resolve(self.default)
        return self


class ModelEfforts(Contract):
    model: ExactReference
    efforts: Annotated[tuple[Identifier, ...], Field(min_length=1, max_length=16)]

    @model_validator(mode="after")
    def unique_efforts(self):
        if len(set(self.efforts)) != len(self.efforts):
            raise ValueError("duplicate model effort")
        return self


class ModelSelection(Contract):
    model: ExactReference
    effort: Identifier


class ModelOverride(Contract):
    model: ExactReference | None = None
    effort: Identifier | None = None

    @model_validator(mode="after")
    def selected_field(self):
        if self.model is None and self.effort is None:
            raise ValueError("model override selects at least one field")
        return self


class RoleModelSlot(Contract):
    role: Identifier
    supported: Annotated[tuple[ModelEfforts, ...], Field(min_length=1, max_length=64)]
    default: ModelSelection

    def resolve(
        self, model: ExactReference | None, effort: str | None
    ) -> ModelSelection:
        selection = ModelSelection(
            model=model or self.default.model, effort=effort or self.default.effort
        )
        if not any(
            item.model == selection.model and selection.effort in item.efforts
            for item in self.supported
        ):
            raise ForgeError(
                "research_model_unsupported", "model/effort pairing is not declared"
            )
        return selection

    @model_validator(mode="after")
    def supported_default(self):
        digests = [contract_digest(item.model) for item in self.supported]
        if len(set(digests)) != len(digests):
            raise ValueError("duplicate supported model")
        self.resolve(self.default.model, self.default.effort)
        return self


class ResearchTemplate(Contract):
    schema_version: Literal["forge.research-template.v1"] = "forge.research-template.v1"
    template_id: Identifier
    revision: Identifier
    title: Text
    protocol: ExactReference
    context_policy: ExactReference
    capture_profile: ExactReference
    required_capabilities: Annotated[tuple[Identifier, ...], Field(max_length=128)] = ()
    required_tools: Annotated[tuple[Identifier, ...], Field(max_length=128)]
    parameters: Annotated[tuple[ParameterSlot, ...], Field(max_length=128)] = ()
    model_slots: Annotated[tuple[RoleModelSlot, ...], Field(max_length=64)] = ()
    maximum_spend_micros: Annotated[int, Field(strict=True, ge=0, le=2**53 - 1)]
    maximum_concurrency: Annotated[int, Field(strict=True, ge=1, le=10000)]

    @model_validator(mode="after")
    def unique_slots(self):
        groups = [
            self.required_capabilities,
            self.required_tools,
            tuple(slot.name for slot in self.parameters),
            tuple(slot.role for slot in self.model_slots),
        ]
        if any(len(set(group)) != len(group) for group in groups):
            raise ValueError("duplicate template capability, tool or slot")
        return self


