class ResearchPlan(Contract):
    schema_version: Literal["forge.research-plan.v1"] = "forge.research-plan.v1"
    project_id: Identifier
    method: ExactReference
    template: ExactReference
    program: ExactReference
    skill: ExactReference
    mcp_contract: ExactReference
    protocol: ExactReference
    context_policy: ExactReference
    capture_profile: ExactReference
    parameters: Annotated[tuple[ResolvedParameter, ...], Field(max_length=128)]
    roles: Annotated[tuple[ResolvedRole, ...], Field(max_length=64)]
    inputs: Annotated[tuple[ExactReference, ...], Field(max_length=1024)]
    evaluator: ExactReference
    spend_ceiling_micros: Annotated[int, Field(strict=True, ge=0, le=2**53 - 1)]
    concurrency: Annotated[int, Field(strict=True, ge=1, le=10000)]

    @property
    def digest_sha256(self) -> Digest:
        return contract_digest(self)

    @model_validator(mode="after")
    def canonical_slots(self):
        for keys in (
            tuple(item.name for item in self.parameters),
            tuple(item.role for item in self.roles),
        ):
            if keys != tuple(sorted(set(keys))):
                raise ValueError("resolved plan slots must be unique and sorted")
        return self


def exact_release(reference, release, kind, identity, revision):
    if (
        reference.authority != "forge"
        or reference.kind != kind
        or reference.record_id != identity
        or reference.revision != revision
        or reference.digest_sha256 != contract_digest(release)
    ):
        raise ForgeError(
            "research_release_conflict", "research release differs from exact pin"
        )


def resolve_research_plan(
    request: ResearchPlanRequest,
    *,
    template: ResearchTemplate,
    method: ResearchMethodRelease,
    available_capabilities: frozenset[str],
    available_tools: frozenset[str],
    program: ExactReference,
    skill: ExactReference,
    mcp_contract: ExactReference,
) -> ResearchPlan:
    """Resolve once; create revalidates authority/capacity against these same bytes."""
    request = ResearchPlanRequest.model_validate_json(request.model_dump_json())
    template = ResearchTemplate.model_validate_json(template.model_dump_json())
    method = ResearchMethodRelease.model_validate_json(method.model_dump_json())
    exact_release(
        request.method, method, "research_method", method.method_id, method.revision
    )
    exact_release(
        method.template,
        template,
        "research_template",
        template.template_id,
        template.revision,
    )
    if any(
        getattr(method, name) != getattr(template, name)
        for name in ("protocol", "context_policy", "capture_profile")
    ):
        raise ForgeError(
            "research_pairing_incompatible", "recording profile pairing differs"
        )
    if (method.program, method.skill, method.mcp_contract) != (
        program,
        skill,
        mcp_contract,
    ):
        raise ForgeError(
            "research_pairing_incompatible", "installed program/skill/tool pin differs"
        )
    if (
        not set(template.required_capabilities) <= available_capabilities
        or not set(template.required_tools) <= available_tools
    ):
        raise ForgeError(
            "research_capability_missing", "required research capabilities are absent"
        )
    if (
        request.spend_ceiling_micros > template.maximum_spend_micros
        or request.concurrency > template.maximum_concurrency
    ):
        raise ForgeError(
            "research_limits_exceeded", "research limits exceed declared bounds"
        )
    slots = {slot.name: slot for slot in template.parameters}
    roles = {slot.role: slot for slot in template.model_slots}
    if set(request.parameters) - slots.keys() or set(request.roles) - roles.keys():
        raise ForgeError(
            "research_slot_unknown", "undeclared parameter or role selection"
        )
    if not roles and (request.model is not None or request.effort is not None):
        raise ForgeError(
            "research_slot_unknown", "template declares no model selection slots"
        )
    parameters = {}
    for name, slot in sorted(slots.items()):
        value = request.parameters.get(name, slot.default)
        if value is None:
            if slot.required:
                raise ForgeError(
                    "research_parameter_missing", "required parameter is absent"
                )
            continue
        parameters[name] = slot.resolve(value)
    selections = {}
    for role, slot in sorted(roles.items()):
        named = request.roles.get(role)
        selections[role] = slot.resolve(
            named.model if named and named.model is not None else request.model,
            named.effort if named and named.effort is not None else request.effort,
        )
    return ResearchPlan(
        project_id=request.project_id,
        method=request.method,
        template=method.template,
        program=method.program,
        skill=method.skill,
        mcp_contract=method.mcp_contract,
        protocol=method.protocol,
        context_policy=method.context_policy,
        capture_profile=method.capture_profile,
        parameters=tuple(
            ResolvedParameter(name=name, value=value)
            for name, value in parameters.items()
        ),
        roles=tuple(
            ResolvedRole(role=role, selection=value)
            for role, value in selections.items()
        ),
        inputs=request.inputs,
        evaluator=request.evaluator,
        spend_ceiling_micros=request.spend_ceiling_micros,
        concurrency=request.concurrency,
    )
